"""Round-six native pencil drawings. Coordinates are art pixels, never samples.
Rectangles and paths are authored below; wrapping only translates those paths.
The saved C6-before layers preserve accepted objects and station surfaces.
"""
from PIL import Image,ImageDraw
from draw_proofs import BASE,REVIEW,S,c,pts
from redraw_proofs_c1 import Pen
from finish_c5 import remap

B=REVIEW/'C6-before'
FAILED=['keep','temple','manor','crypt','cave_rock','cave_ice','cave_crystal','cave_lava','dungeon_sewer','station_hydro','yard']

def load(n,t):return Image.open(B/f'C-layer-{n}-{t}.png').convert('RGBA')
def polygons(im,data,ink,wrap=False):
 for path in data.split(';'):
  if not path.strip():continue
  points=pts(path)
  for dx,dy in ([(x,y) for y in (-144,0,144) for x in (-144,0,144)] if wrap else [(0,0)]):
   ImageDraw.Draw(im).polygon([(x+dx,y+dy) for x,y in points],fill=c(*ink))
def strokes(im,data,ink,width=1,wrap=False):
 for path in data.split(';'):
  if not path.strip():continue
  points=pts(path)
  for dx,dy in ([(x,y) for y in (-144,0,144) for x in (-144,0,144)] if wrap else [(0,0)]):
   ImageDraw.Draw(im).line([(x+dx,y+dy) for x,y in points],fill=c(*ink),width=width)
def rects(im,data,ink):
 d=ImageDraw.Draw(im)
 for v in data.split(';'):
  if v.strip():d.rectangle(tuple(map(int,v.split(','))),fill=c(*ink))

