def masonry(n):
 # Face courses are construction. Unequal block dimensions are chosen per look.
 cfg={
 'keep':('iron',2,'limestone',2,[(48,62,[-10,24,63,108,150]),(64,79,[-24,15,52,89,129,155]),(81,94,[-8,34,77,116,155])]),
 'temple':('sandstone',1,'sandstone',2,[(48,69,[-20,39,94,160]),(71,94,[-6,61,122,170])]),
 'crypt':('dark-masonry',2,'dark-masonry',3,[(48,60,[-13,21,58,102,154]),(62,77,[-25,8,49,88,125,155]),(79,94,[-9,29,73,113,155])]),
 'dungeon_sewer':('brick',2,'brick',3,[(48,58,[-9,23,57,93,126,160]),(60,70,[-20,10,44,79,114,150]),(72,82,[-7,29,65,99,132,170]),(84,94,[-22,15,50,85,120,155])]),
 'yard':('roof-slate',1,'yard-cobble',2,[(48,66,[-16,21,64,110,153]),(68,82,[-28,7,49,88,130,165]),(84,94,[-6,36,77,119,154])])}[n]
 tr,ts,r,s,courses=cfg
 w=Image.new('RGBA',(144,96),c('void-mass',2));d=Pen(w);d.r((0,8,143,47),tr,ts)
 # Narrow recessed mortar and partial arrises, with no nested rectangles.
 for y,z,ends in courses:
  for a,b in zip(ends,ends[1:]):
   d.r((a,y,b-2,z),r,s)
   d.r((a,y,a,z-1),r,min(s+1,6))
   d.r((a+1,y,b-5,y),r,min(s+1,6))
   d.r((a,z-1,b-2,z),tr,ts)
 d.r((0,95,143,95),S[n][1][0],1)
 return w

