def manor_floor():
 f=Image.new('RGBA',(144,144),c('parquet',3));d=Pen(f)
 # Fine panel strips are construction, with grain, not repeated wavy ribbons.
 for row in range(3):
  for col in range(3):
   x,y=col*48,row*48
   d.r((x,y,x+47,y),'timber',4);d.r((x,y,x,y+47),'timber',4)
   for off in (15,31):
    if (row+col)%2:d.r((x+off,y+1,x+off,y+47),'timber',4)
    else:d.r((x+1,y+off,x+47,y+off),'timber',4)
 strokes(f,WOOD,('parquet',4),1)
 # Unequal knots interrupt three boards, all at different scales.
 polygons(f,'9,20 14,18 20,18 25,20 21,22 14,22;80,32 83,28 86,30 87,36 84,40 81,37;111,126 118,124 125,125 129,127 124,130 116,130 111,128',('timber',4))
 strokes(f,'14,20 20,20;83,32 84,36;116,127 124,127',('parquet',3),1)
 return f

