def prop_repairs(n,p):
 if n=='station_hydro':
  # Reassign entire substantial planes; preserve silhouettes and all surfaces.
  remap(p,('planters',4),('planters',3))
  remap(p,('overgrowth',4),('overgrowth',5))
  # Pot face uses a cool leak shadow at 34 L*, >15 from its local 50 L* floor.
  remap(p,('planters',3),('leaks',2))
 if n in ('cave_ice','cave_crystal'):
  # Outline cleanup is an explicit pencil list, not erosion or a filter.
  if n=='cave_ice':
   rects(p,'33,18,33,19;34,20,34,21;39,38,40,39;38,40,39,41;35,42,37,42;10,41,11,41;8,39,9,40;7,37,7,38',('snowdrift',4))
  else:
   rects(p,'41,36,41,38;40,39,41,40;38,41,39,41;37,42,38,42;6,38,6,39;7,40,8,41;9,42,11,42;12,43,14,43',('dark-rock',6))
   # Left shard's exposed descending edge is one pixel throughout.
   strokes(p,'9,30 9,32 12,35 14,37',('violet-crystal',5),1)
 return p

def build():
 floors={'keep':keep_floor,'temple':temple_floor,'manor':manor_floor,'crypt':crypt_floor,'cave_rock':rock_floor,'cave_ice':ice_floor,'cave_crystal':crystal_floor,'cave_lava':lava_floor,'dungeon_sewer':sewer_floor,'yard':yard_floor}
 failed=set(__import__('json').loads((REVIEW/'critic-C-6.json').read_text())['failed'])
 for n in FAILED:
  f=floors[n]() if n in floors else load(n,'floor')
  w=manor_wall() if n=='manor' else cave_wall(n) if n.startswith('cave_') else masonry_finish(masonry(n),n) if n in CAP else load(n,'wall')
  p=prop_repairs(n,load(n,'prop'))
  # Further authored corrections discovered by saved-file inspection.
  from finish_c6 import finish
  finish(n,f,w,p)
  im=f.copy();im.paste(w,(0,0));im.alpha_composite(p,(86,96))
  im.save(BASE/f'proof/{n}.png');im.convert('L').convert('RGBA').save(BASE/f'proof/{n}-grey.png')
  for t,a in [('floor',f),('wall',w),('prop',p)]:a.save(REVIEW/f'C-layer-{n}-{t}.png')
  study='building-yard' if n=='yard' else n
  if f'canon/swatches/{study}.png' in failed:
   sw=Image.new('RGBA',(48,48));sw.paste(w.crop((0,48,48,72)),(0,0));sw.paste(f.crop((0,96,48,120)),(0,24));d=Pen(sw)
   if n=='keep':d.r((40,0,44,23),'wood-oak',3);d.r((40,0,40,23),'wood-oak',5);d.r((42,7,42,19),'wood-oak',2)
   if n=='temple':d.r((0,22,47,23),'brass',2);d.r((0,22,47,22),'brass',3)
   if n=='cave_crystal':
    d.p('27,7 32,3 36,7 36,18 31,22 27,18','violet-crystal',1);d.p('28,8 31,5 31,20 28,17','violet-crystal',5);d.p('32,5 35,8 35,17 32,20','violet-crystal',4)
   if n=='cave_lava':sw.paste(w.crop((54,48,102,72)),(0,0));sw.paste(f.crop((15,96,63,120)),(0,24))
   from finish_c6 import finish_study
   finish_study(n,sw)
   sw.save(BASE/f'canon/swatches/{study}.png')
 guide=Image.open(B/'canon/style-guide.png').convert('RGB')
 from draw_style_samples import SWATCHES
 for i,n in enumerate(SWATCHES):
  if f'canon/swatches/{n}.png' in failed:guide.paste(Image.open(BASE/f'canon/swatches/{n}.png'),(48+i%7*240,800+i//7*94))
 guide.paste(Image.open(BASE/'canon/swatches/keep.png'),(1032,1524));guide.save(BASE/'canon/style-guide.png')
 for n in S:
  f=Image.open(REVIEW/f'C-layer-{n}-floor.png');repeat=Image.new('RGBA',(432,432))
  for y in range(3):
   for x in range(3):repeat.paste(f,(144*x,144*y))
  repeat.save(REVIEW/f'proof-3x3repeat-{n}.png')
 print('Saved only the 32 failed deliverables and refreshed all floor repeats.')
if __name__=='__main__':build()
